suppressPackageStartupMessages({library(data.table);library(jsonlite);library(GenomicRanges);library(rtracklayer);library(Biostrings)})
p='output/followup_analysis/';s=fread(paste0(p,'tables/summit_normalized_positions.tsv.gz'))[kind=='3UTR'];f=fread('data/results_round2/features.tsv.gz');f=f[feature_id%in%s$feature_id];seg=lapply(f$segments_0based_half_open,fromJSON);lens=vapply(seg,nrow,integer(1));m=do.call(rbind,seg);ix=rep(seq_len(nrow(f)),lens);gr=GRanges(f$chrom[ix],IRanges(m[,1]+1,m[,2]));tw=TwoBitFile('data/reference_followup/hg38.2bit');seqs=import(tw,which=gr);parts=split(as.character(seqs),ix);utr=DNAStringSet(vapply(parts,paste,character(1),collapse=''));ord=as.integer(names(parts));f=f[ord];utr[f$strand=='-']=reverseComplement(utr[f$strand=='-']);num=vcountPattern('TAG',utr);starts=width(utr)-2;u=data.table(feature_id=f$feature_id,length=width(utr),UAG=num,possible_starts=starts);u=merge(u,s[,.(summits=.N),by=feature_id],by='feature_id');fwrite(u,paste0(p,'tables/UTR_motif_background_models.tsv.gz'),sep='\t');mot=fread(paste0(p,'tables/UAG_per_site.tsv.gz'));obs=sum(mot[peak_id%in%s$peak_id,observed_UAG]);density=obs/(nrow(s)*49);expected=sum(u$summits*u$UAG/u$possible_starts)/sum(u$summits);res=data.table(analysis='ZFP36-style UTR sequence exposure sensitivity',summit_windows=nrow(s),unique_UTR_models=nrow(u),observed_motif_per_possible_start=density,background_motif_per_possible_start=expected,fold=density/expected,randomizations=0,background='Full sequence of each assigned longest matching spliced UTR; weighted by number of summits assigned to it; analytic sequence exposure,not PARpipe shuffle');fwrite(res,paste0(p,'tables/UAG_UTR_sequence_background.tsv'),sep='\t')
library(ggplot2)
dinuc=sum(mot[peak_id%in%s$peak_id,expected_UAG])/(nrow(s)*49);b=data.table(source=c('Observed summit windows','Dinucleotide-shuffled windows','Matched full UTR sequence'),UAG_per_start=c(density,dinuc,expected),N=nrow(s));fwrite(b,paste0(p,'tables/UAG_background_comparison.tsv'),sep='\t');fig=ggplot(b,aes(source,UAG_per_start,fill=source))+geom_col()+theme_bw()+theme(legend.position='none')+labs(x=NULL,y='UAG occurrences per possible trinucleotide start',title='Orthogonal UTR-sequence motif background',subtitle='Same 26,504 UTR-associated summit windows; 8,869 matched UTR models');for(e in c('png','pdf'))ggsave(paste0(p,'figures/UAG_UTR_background.',e),fig,width=10,height=6,dpi=220)
